Use a stack to match each closing bracket with the most recent opening bracket. Time: O(n); auxiliary space: O(n), where n is s.length.

```javascript
function solve(s) {
  const stack = [];
  const matching = { ')': '(', ']': '[', '}': '{' };

  for (const ch of s) {
    if (ch === '(' || ch === '[' || ch === '{') {
      stack.push(ch);
    } else if (ch === ')' || ch === ']' || ch === '}') {
      if (stack.length === 0 || stack.pop() !== matching[ch]) {
        return false;
      }
    } else {
      return false;
    }
  }

  return stack.length === 0;
}
```

Call solve(s) directly; no imports, exports, or stdin/stdout are needed.

